106	// without any opening bracket or quote. "U.S.A." style initialisms are not
107	// listed: they usually do end a sentence when they come last, and guessing
108	// otherwise would trade one error for another.
109	const ABBREVIATIONS = new Set(['mr', 'mrs', 'ms', 'dr', 'prof', 'st', 'sr', 'jr', 'vs', 'e.g', 'i.e']);
110	
111	// A terminator run ("." "?!" "...") plus any closing quotes or brackets, and
112	// only where whitespace or the end of the text follows. Requiring that keeps
113	// decimals ("3.14"), domains ("example.com") and "a.b.c" in one piece.
114	const TERMINATOR_PATTERN = /([.!?]+)(["'”’)\]]*)(?=\s|$)/g;
115	
116	function endsWithAbbreviation(before) {
117	  const last = before.match(/(\S+)$/);
118	  if (last === null) {
119	    return false;
120	  }
121	  const word = last[1].replace(/^["'“‘(\[]+/, '').toLowerCase();
122	  return ABBREVIATIONS.has(word);
123	}
