129	 * terminator run, or at the end of the text. A lone period after a known
130	 * abbreviation does not end a sentence.
131	 *
132	 * @param {string} text
133	 * @returns {number}
134	 */
135	function sentenceCount(text) {
136	  assertText('sentenceCount', text);
137	  let count = 0;
138	  let start = 0;
139	  for (const match of text.matchAll(TERMINATOR_PATTERN)) {
140	    const before = text.slice(start, match.index);
141	    if (match[1] === '.' && endsWithAbbreviation(before)) {
142	      continue;
143	    }
144	    if (tokenize(before).length > 0) {
145	      count += 1;
146	    }
